function w(n) 
{
  if(n==null) return width
  return width*n
}

function h(n) 
{
  if(n==null) return height
  return height*n
}

function hsbShift(col, h, s, b)
{
    return color(hue(col)+h, saturation(col)+s, brightness(col)+b)
}

function randNeg(n) 
{
  return (n==null)?(random() < 0.5 ? 1:-1):(random() < 0.5 ? n:-n)
}

function ease(n) 
{
  return n**3
}

class particle 
{
  constructor(sx, sy, sc, ss, sd, sl, ls, tag, others) {
    this.tag = tag
    this.pos = createVector(sx, sy)
    this.col = sc
    this.siz = 1
    this.asiz = ss
    this.dir = sd
    this.spd = (this.tag=="trunk")?2:random(0.25, 2)
    this.life = sl
    this.lifespan = ls
    this.others = others
    this.thshift = random(-1, 1)*0
    this.tsshift = random(1)*0
    this.tbshift = random(-1)*0
    this.rsiz = this.asiz*this.siz
  }

  kill() 
	{
    let index = this.others.indexOf(this)
    if(index > -1) 
		{
      this.others.splice(index, 1)
    }
  }

  update() 
	{
    this.rsiz = this.asiz*this.siz
    this.pos.add(createVector(cos(radians(this.dir))*this.spd, sin(radians(this.dir))*this.spd))
    this.dir += random(-.9, 1)*(this.tag == "trunk" && this.siz > 0.7 ? 1:map(this.life, 0, this.lifespan, 1, 5))
    if(random() < (this.tag=="branch" ? 0.003:0.005) && this.tag!="trunk") this.dir += randNeg(72)*0
    this.siz = lerp(this.siz, 0, random(0.015))

    if(this.rsiz < 0.1 || this.spd > this.rsiz) 
		{
      this.kill()
    }

    this.col = hsbShift(this.col, random(this.thshift), random(this.tsshift), random(this.tbshift))

    if(random() < 0.03 && this.tag=="trunk" && this.siz < .55) 
		{
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir+randNeg(random(15, 30)), this.life, this.lifespan, "branch", this.others))
    }

    if(random() < 0.01 && this.tag=="branch") 
		{
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, this.rsiz, this.dir, this.life, this.lifespan, "branch", this.others))
    }

    if(random() < map(this.siz, 0, 0.25, 0.5, 0.3) && this.tag=="branch" && this.siz < 0.25) 
		{
      this.others.push(new particle(this.pos.x, this.pos.y, this.col, (this.siz**0.5)*this.rsiz, this.dir+randNeg(random(5, 20)), 0, random(this.lifespan*0.05), "twig", this.others))
    }

    noStroke()
    fill(this.col)
    circle(this.pos.x, this.pos.y, this.siz*this.asiz)

    if(this.life > this.lifespan) 
		{
			let chance=round(random(3))
			strokeWeight(random(4))
			if(chance==0) stroke("green")
			else stroke(0,50,0)
      line(this.pos.x, this.pos.y,this.pos.x, this.pos.y+random(50),)
			this.kill()
    }
    this.life++
  }
}

let PARTS = []
let count = 2

function setup() {
  createCanvas(1000, 1000);
  background(255)
  for(let i = 0; i < count; i++) 
	{
    PARTS.push(new particle(w(0.5), h(0.95), "#000", 100, 270, 0, 500, "trunk", PARTS))
  }
	fill(0)
	rect(0,height,width,-40)
}

function draw() {
	push()
	translate(-250,100)
  for(var p of PARTS) 
	{
    for(let i = 0; i < 1; i++) p.update()
  }
	pop()
	strokeWeight(54)
	line(700,height,700,height-85)
	strokeWeight(33)
	circle(700,height-85,20)
}

function smoothstep(start, end, amount) 
{
  amount = Math.max(0, Math.min(1, amount));
  return (amount * amount * (3 - 2 * amount)) * (end - start) + start;
}



// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}

